PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "healthcare_aiservice" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "name" varchar(100) NOT NULL, "service_type" varchar(50) NOT NULL UNIQUE, "description" text NOT NULL, "is_enabled" bool NOT NULL, "endpoint" varchar(200) NOT NULL);
CREATE TABLE IF NOT EXISTS "healthcare_department" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "name" varchar(80) NOT NULL UNIQUE, "description" text NOT NULL, "status" varchar(10) NOT NULL);
CREATE TABLE IF NOT EXISTS "healthcare_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "role" varchar(12) NOT NULL, "phone" varchar(20) NOT NULL, "avatar" varchar(100) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "healthcare_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "healthcare_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "healthcare_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "healthcare_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "healthcare_auditlog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "action" varchar(50) NOT NULL, "resource" varchar(100) NOT NULL, "object_id" varchar(64) NOT NULL, "description" varchar(300) NOT NULL, "ip_address" char(39) NULL, "created_at" datetime NOT NULL, "user_id" bigint NULL REFERENCES "healthcare_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "healthcare_examinationreport" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "findings" text NOT NULL, "conclusion" text NOT NULL, "status" varchar(12) NOT NULL, "published_at" datetime NULL, "order_id" bigint NOT NULL UNIQUE REFERENCES "healthcare_examinationorder" ("id") DEFERRABLE INITIALLY DEFERRED, "published_by_id" bigint NULL REFERENCES "healthcare_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "healthcare_medicalfile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "file" varchar(100) NOT NULL, "original_name" varchar(255) NOT NULL, "file_type" varchar(30) NOT NULL, "size" bigint unsigned NOT NULL CHECK ("size" >= 0), "uploaded_at" datetime NOT NULL, "order_id" bigint NOT NULL REFERENCES "healthcare_examinationorder" ("id") DEFERRABLE INITIALLY DEFERRED, "uploaded_by_id" bigint NOT NULL REFERENCES "healthcare_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "healthcare_medicalrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "record_no" varchar(24) NOT NULL UNIQUE, "chief_complaint" text NOT NULL, "present_illness" text NOT NULL, "past_history" text NOT NULL, "examination" text NOT NULL, "diagnosis" text NOT NULL, "treatment" text NOT NULL, "status" varchar(12) NOT NULL, "confirmed_at" datetime NULL, "appointment_id" bigint NOT NULL UNIQUE REFERENCES "healthcare_appointment" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "healthcare_medicalrecordcorrection" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content" text NOT NULL, "created_at" datetime NOT NULL, "author_id" bigint NOT NULL REFERENCES "healthcare_user" ("id") DEFERRABLE INITIALLY DEFERRED, "record_id" bigint NOT NULL REFERENCES "healthcare_medicalrecord" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "healthcare_medicine" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "name" varchar(120) NOT NULL, "specification" varchar(100) NOT NULL, "unit" varchar(30) NOT NULL, "price" decimal NOT NULL, "stock" integer unsigned NOT NULL CHECK ("stock" >= 0), "is_active" bool NOT NULL, CONSTRAINT "uq_medicine_specification" UNIQUE ("name", "specification"));
CREATE TABLE IF NOT EXISTS "healthcare_patientprofile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "patient_no" varchar(20) NOT NULL UNIQUE, "gender" varchar(10) NOT NULL, "birth_date" date NULL, "address" varchar(300) NOT NULL, "blood_group" varchar(8) NOT NULL, "allergies" text NOT NULL, "medical_history" text NOT NULL, "emergency_contact_name" varchar(80) NOT NULL, "emergency_contact_phone" varchar(20) NOT NULL, "user_id" bigint NOT NULL UNIQUE REFERENCES "healthcare_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "healthcare_aianalysistask" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "status" varchar(12) NOT NULL, "result" text NOT NULL CHECK ((JSON_VALID("result") OR "result" IS NULL)), "error_message" text NOT NULL, "created_by_id" bigint NOT NULL REFERENCES "healthcare_user" ("id") DEFERRABLE INITIALLY DEFERRED, "service_id" bigint NOT NULL REFERENCES "healthcare_aiservice" ("id") DEFERRABLE INITIALLY DEFERRED, "file_id" bigint NOT NULL REFERENCES "healthcare_medicalfile" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "healthcare_patientprofile" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "healthcare_prescription" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "prescription_no" varchar(24) NOT NULL UNIQUE, "status" varchar(12) NOT NULL, "notes" text NOT NULL, "doctor_id" bigint NOT NULL REFERENCES "healthcare_doctorprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "record_id" bigint NOT NULL REFERENCES "healthcare_medicalrecord" ("id") DEFERRABLE INITIALLY DEFERRED, "dispensed_at" datetime NULL);
CREATE TABLE IF NOT EXISTS "healthcare_prescriptionitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "dosage" varchar(80) NOT NULL, "frequency" varchar(80) NOT NULL, "duration" varchar(80) NOT NULL, "quantity" integer unsigned NOT NULL CHECK ("quantity" >= 0), "medicine_id" bigint NOT NULL REFERENCES "healthcare_medicine" ("id") DEFERRABLE INITIALLY DEFERRED, "prescription_id" bigint NOT NULL REFERENCES "healthcare_prescription" ("id") DEFERRABLE INITIALLY DEFERRED, "unit_price_snapshot" decimal NULL);
CREATE TABLE IF NOT EXISTS "healthcare_doctorschedule" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "date" date NOT NULL, "start_time" time NOT NULL, "end_time" time NOT NULL, "slot_minutes" smallint unsigned NOT NULL CHECK ("slot_minutes" >= 0), "is_active" bool NOT NULL, "doctor_id" bigint NOT NULL REFERENCES "healthcare_doctorprofile" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_doctor_schedule_period" UNIQUE ("doctor_id", "date", "start_time", "end_time"));
CREATE TABLE IF NOT EXISTS "healthcare_appointmentslot" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "start_time" time NOT NULL, "end_time" time NOT NULL, "status" varchar(12) NOT NULL, "schedule_id" bigint NOT NULL REFERENCES "healthcare_doctorschedule" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_schedule_slot_period" UNIQUE ("schedule_id", "start_time", "end_time"));
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "healthcare_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "healthcare_doctorprofile_departments" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "doctorprofile_id" bigint NOT NULL REFERENCES "healthcare_doctorprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "department_id" bigint NOT NULL REFERENCES "healthcare_department" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "healthcare_doctorprofile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "doctor_no" varchar(20) NOT NULL UNIQUE, "title" varchar(80) NOT NULL, "specialty" varchar(200) NOT NULL, "introduction" text NOT NULL, "is_available" bool NOT NULL, "department_id" bigint NOT NULL REFERENCES "healthcare_department" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL UNIQUE REFERENCES "healthcare_user" ("id") DEFERRABLE INITIALLY DEFERRED, "is_super_doctor" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "healthcare_examinationitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "name" varchar(120) NOT NULL UNIQUE, "category" varchar(16) NOT NULL, "price" decimal NOT NULL, "is_active" bool NOT NULL, "description" varchar(300) NOT NULL);
CREATE TABLE IF NOT EXISTS "healthcare_examinationorder" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "order_no" varchar(24) NOT NULL UNIQUE, "type" varchar(12) NOT NULL, "status" varchar(16) NOT NULL, "clinical_question" text NOT NULL, "completed_at" datetime NULL, "doctor_id" bigint NOT NULL REFERENCES "healthcare_doctorprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "record_id" bigint NOT NULL REFERENCES "healthcare_medicalrecord" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "healthcare_patientprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "item_name_snapshot" varchar(120) NOT NULL, "price_snapshot" decimal NOT NULL, "item_id" bigint NULL REFERENCES "healthcare_examinationitem" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "healthcare_inpatientadmission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "admission_no" varchar(24) NOT NULL UNIQUE, "ward" varchar(80) NOT NULL, "bed_no" varchar(30) NOT NULL, "admission_diagnosis" text NOT NULL, "discharge_summary" text NOT NULL, "status" varchar(12) NOT NULL, "admitted_at" datetime NULL, "discharged_at" datetime NULL, "appointment_id" bigint NULL REFERENCES "healthcare_appointment" ("id") DEFERRABLE INITIALLY DEFERRED, "attending_doctor_id" bigint NOT NULL REFERENCES "healthcare_doctorprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "department_id" bigint NOT NULL REFERENCES "healthcare_department" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "healthcare_patientprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "daily_rate_snapshot" decimal NOT NULL, "bed_id" bigint NULL REFERENCES "healthcare_wardbed" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "healthcare_medicinestockmovement" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "movement_type" varchar(16) NOT NULL, "quantity" integer NOT NULL, "balance_after" integer unsigned NOT NULL CHECK ("balance_after" >= 0), "note" varchar(200) NOT NULL, "created_at" datetime NOT NULL, "medicine_id" bigint NOT NULL REFERENCES "healthcare_medicine" ("id") DEFERRABLE INITIALLY DEFERRED, "operator_id" bigint NULL REFERENCES "healthcare_user" ("id") DEFERRABLE INITIALLY DEFERRED, "prescription_id" bigint NULL REFERENCES "healthcare_prescription" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "healthcare_wardbed" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "ward_name" varchar(80) NOT NULL, "bed_no" varchar(30) NOT NULL, "daily_rate" decimal NOT NULL, "is_active" bool NOT NULL, "is_occupied" bool NOT NULL, "department_id" bigint NOT NULL REFERENCES "healthcare_department" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "uq_ward_bed_number" UNIQUE ("ward_name", "bed_no"));
CREATE TABLE IF NOT EXISTS "healthcare_billingrecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "description" varchar(200) NOT NULL, "amount" decimal NOT NULL, "status" varchar(12) NOT NULL, "appointment_id" bigint NULL REFERENCES "healthcare_appointment" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "healthcare_patientprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "bill_no" varchar(24) NOT NULL UNIQUE, "category" varchar(20) NOT NULL, "paid_at" datetime NULL, "payment_method" varchar(30) NOT NULL, "prescription_id" bigint NULL UNIQUE REFERENCES "healthcare_prescription" ("id") DEFERRABLE INITIALLY DEFERRED, "admission_id" bigint NULL UNIQUE REFERENCES "healthcare_inpatientadmission" ("id") DEFERRABLE INITIALLY DEFERRED, "examination_id" bigint NULL UNIQUE REFERENCES "healthcare_examinationorder" ("id") DEFERRABLE INITIALLY DEFERRED, "inpatient_admission_id" bigint NULL REFERENCES "healthcare_inpatientadmission" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "ck_billing_amount_non_negative" CHECK ("amount" >= '0'));
CREATE TABLE IF NOT EXISTS "healthcare_appointment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "appointment_no" varchar(24) NOT NULL UNIQUE, "status" varchar(16) NOT NULL, "reason" text NOT NULL, "cancelled_at" datetime NULL, "completed_at" datetime NULL, "doctor_id" bigint NOT NULL REFERENCES "healthcare_doctorprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "patient_id" bigint NOT NULL REFERENCES "healthcare_patientprofile" ("id") DEFERRABLE INITIALLY DEFERRED, "department_id" bigint NULL REFERENCES "healthcare_department" ("id") DEFERRABLE INITIALLY DEFERRED, "slot_id" bigint NOT NULL REFERENCES "healthcare_appointmentslot" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
